import os
import boto3

from botocore.exceptions import NoCredentialsError, PartialCredentialsError


def summarize_invoice_fields(invoice_fields):
    try:
        bedrock = boto3.client('bedrock', region_name='us-east-1')
        response = bedrock.invoke_model(
            model_id='amazon.titan-text-express-v1',
            body={
                'inputText': str(invoice_fields),
                'textGenerationConfig': {
                    'maxTokenCount': 512,
                    'temperature': 0.5,
                    'topP': 0.9
                }
            }
        )
        summary = response['outputText']
        return summary
    except (NoCredentialsError, PartialCredentialsError) as e:
        print(f'AWS credentials error: {e}')
        return None
    except Exception as e:
        print(f'Error summarizing invoice fields: {e}')
        return None

from typing import Any, Dict, List

class DocumentRequest:
    def __init__(self, document_type: str, document_content: bytes):
        self.document_type = document_type
        self.document_content = document_content

    def to_dict(self) -> Dict[str, Any]:
        return {
            'document_type': self.document_type,
            'document_content': self.document_content
        }

class DocumentResponse:
    def __init__(self, extracted_fields: Dict[str, Any], confidence_scores: Dict[str, float]):
        self.extracted_fields = extracted_fields
        self.confidence_scores = confidence_scores

    def to_dict(self) -> Dict[str, Any]:
        return {
            'extracted_fields': self.extracted_fields,
            'confidence_scores': self.confidence_scores
        }

def normalize_document_fields(extracted_fields: Dict[str, Any]) -> Dict[str, Any]:
    normalized_fields = {}
    for key, value in extracted_fields.items():
        normalized_fields[key.lower().replace(' ', '_')] = value
    return normalized_fields

