import boto3

def validate_fields(document):
    comprehend = boto3.client('comprehend')
    try:
        response = comprehend.detect_sentiment(Text=document['text'], LanguageCode='en')
        sentiment = response['Sentiment']
        confidence_score = response['SentimentScore'][sentiment]
        if confidence_score < 0.5:
            return False, 'Low confidence score'
        else:
            return True, 'Validation passed'
    except Exception as e:
        return False, str(e)

import boto3

def extract_receipt_fields(receipt_image):
    textract_client = boto3.client('textract')
    response = textract_client.analyze_document(
        Document={'Bytes': receipt_image},
        FeatureTypes=['FORMS', 'TABLES']
    )
    merchant = None
    tax = None
    total = None
    items = []
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            if 'Merchant' in block['Text']:
                merchant = block['Text'].replace('Merchant', '').strip()
            elif 'Tax' in block['Text']:
                tax = block['Text'].replace('Tax', '').strip()
            elif 'Total' in block['Text']:
                total = block['Text'].replace('Total', '').strip()
        elif block['BlockType'] == 'TABLE':
            for relationship in block['Relationships']:
                if relationship['Type'] == 'CHILD':
                    for child_id in relationship['Ids']:
                        child_block = next(b for b in response['Blocks'] if b['Id'] == child_id)
                        if child_block['BlockType'] == 'CELL':
                            items.append(child_block['Text'].strip())
    return {
        'merchant': merchant,
        'tax': tax,
        'total': total,
        'items': items
    }

import boto3

def extract_invoice_fields(document):
    textract_client = boto3.client('textract')
    response = textract_client.analyze_document(
        Document={'Bytes': document},
        FeatureTypes=['FORMS']
    )
    vendor = None
    date = None
    total = None
    line_items = []
    for item in response.get('Blocks', []):
        if item['BlockType'] == 'KEY_VALUE_SET':
            if item['Text'] == 'Vendor':
                vendor = item['Relationships'][0]['Text']
            elif item['Text'] == 'Date':
                date = item['Relationships'][0]['Text']
            elif item['Text'] == 'Total':
                total = item['Relationships'][0]['Text']
        elif item['BlockType'] == 'LINE':
            line_items.append(item['Text'])
    return {
        'vendor': vendor,
        'date': date,
        'total': total,
        'line_items': line_items
    }
